        if M == v.args[0]:
            return KroneckerDelta(self.args[1], v.args[1], (0, m-1)) * \
                   KroneckerDelta(self.args[2], v.args[2], (0, n-1))

        if isinstance(M, Inverse):
            from sympy.concrete.summations import Sum
            i, j = self.args[1:]
            i1, i2 = symbols("z1, z2", cls=Dummy)
            Y = M.args[0]
            r1, r2 = Y.shape
            return -Sum(M[i, i1]*Y[i1, i2].diff(v)*M[i2, j], (i1, 0, r1-1), (i2, 0, r2-1))

        if self.has(v.args[0]):
            return None

        return S.Zero

def parse_expr(s, local_dict):
    """
    Converts the string "s" to a SymPy expression, in local_dict.

    It converts all numbers to Integers before feeding it to Python and
    automatically creates Symbols.
    """
    global_dict = {}
    exec('from sympy import *', global_dict)
    try:
        a = parse(s.strip(), mode="eval")
    except SyntaxError:
        raise SympifyError("Cannot parse %s." % repr(s))
    a = Transform(local_dict, global_dict).visit(a)
    e = compile(a, "<string>", "eval")
    return eval(e, global_dict, local_dict)

def _from_mathematica_to_tokens(self, code: str):
    tokenizer = self._get_tokenizer()

    # Find strings:
    code_splits: List[typing.Union[str, list]] = []
    while True:
        string_start = code.find("\"")
        if string_start == -1:
            if len(code) > 0:
                code_splits.append(code)
            break
        match_end = re.search(r'(?<!\\)"', code[string_start+1:])
        if match_end is None:
            raise SyntaxError('mismatch in string "  " expression')
        string_end = string_start + match_end.start() + 1
        if string_start > 0:
            code_splits.append(code[:string_start])
        code_splits.append(["_Str", code[string_start+1:string_end].replace('\\"', '"')])
        code = code[string_end+1:]

    # Remove comments:
    for i, code_split in enumerate(code_splits):
        if isinstance(code_split, list):
            continue
        while True:
            pos_comment_start = code_split.find("(*")
            if pos_comment_start == -1:
                break
            pos_comment_end = code_split.find("*)")
            if pos_comment_end == -1 or pos_comment_end < pos_comment_start:
                raise SyntaxError("mismatch in comment (*  *) code")
            code_split = code_split[:pos_comment_start] + code_split[pos_comment_end+2:]
        code_splits[i] = code_split

    # Tokenize the input strings with a regular expression:
    token_lists = [tokenizer.findall(i) if isinstance(i, str) else [i] for i in code_splits]
    tokens = [j for i in token_lists for j in i]

    # Remove newlines at the beginning
    while tokens and tokens[0] == "\n":
        tokens.pop(0)
    # Remove newlines at the end
    while tokens and tokens[-1] == "\n":
        tokens.pop(-1)

    return tokens

def __init__(self, additional_translations=None):
    self.translations = {}

    # update with TRANSLATIONS (class constant)
    self.translations.update(self.TRANSLATIONS)

    if additional_translations is None:
        additional_translations = {}

    # check the latest added translations
    if self.__class__.cache_original != additional_translations:
        if not isinstance(additional_translations, dict):
            raise ValueError('The argument must be dict type')

        # get a transformed additional_translations dictionary
        d = self._compile_dictionary(additional_translations)

        # update cache
        self.__class__.cache_original = additional_translations
        self.__class__.cache_compiled = d

    # merge user's own translations
    self.translations.update(self.__class__.cache_compiled)

def deconstruct(self):
    name, path, args, kwargs = super().deconstruct()
    if self.path != '':
        kwargs['path'] = self.path
    if self.match is not None:
        kwargs['match'] = self.match
    if self.recursive is not False:
        kwargs['recursive'] = self.recursive
    if self.allow_files is not True:
        kwargs['allow_files'] = self.allow_files
    if self.allow_folders is not False:
        kwargs['allow_folders'] = self.allow_folders
    if kwargs.get("max_length") == 100:
        del kwargs["max_length"]
    return name, path, args, kwargs

def formfield(self, **kwargs):
    return super().formfield(**{
        'path': self.path,
        'match': self.match,
        'recursive': self.recursive,
        'form_class': forms.FilePathField,
        'allow_files': self.allow_files,
        'allow_folders': self.allow_folders,
        **kwargs,
    })

def __init__(self, path, *, match=None, recursive=False, allow_files=True,
             allow_folders=False, **kwargs):
    self.path, self.match, self.recursive = path, match, recursive
    self.allow_files, self.allow_folders = allow_files, allow_folders
    super().__init__(choices=(), **kwargs)

    if self.required:
        self.choices = []
    else:
        self.choices = [("", "---------")]

    if self.match is not None:
        self.match_re = re.compile(self.match)

    if recursive:
        for root, dirs, files in sorted(os.walk(self.path)):
            if self.allow_files:
                for f in sorted(files):
                    if self.match is None or self.match_re.search(f):
                        f = os.path.join(root, f)
                        self.choices.append((f, f.replace(path, "", 1)))
            if self.allow_folders:
                for f in sorted(dirs):
                    if f == '__pycache__':
                        continue
                    if self.match is None or self.match_re.search(f):
                        f = os.path.join(root, f)
                        self.choices.append((f, f.replace(path, "", 1)))
    else:
        choices = []
        for f in os.scandir(self.path):
            if f.name == '__pycache__':
                continue
            if (((self.allow_files and f.is_file()) or
                    (self.allow_folders and f.is_dir())) and
                    (self.match is None or self.match_re.search(f.name))):
                choices.append((f.path, f.name))
        choices.sort(key=operator.itemgetter(1))
        self.choices.extend(choices)

    self.widget.choices = self.choices

def render(self, context):
    url = self.url(context)
    if context.autoescape:
        url = conditional_escape(url)
    if self.varname is None:
        return url
    context[self.varname] = url
    return ''

def url(self, context):
    path = self.path.resolve(context)
    return self.handle_simple(path)

def handle_simple(cls, path):
    if apps.is_installed('django.contrib.staticfiles'):
        from django.contrib.staticfiles.storage import staticfiles_storage
        return staticfiles_storage.url(path)
    else:
        return urljoin(PrefixNode.handle_simple("STATIC_URL"), quote(path))

def url(self, name):
    if self.base_url is None:
        raise ValueError("This file is not accessible via a URL.")
    url = filepath_to_uri(name)
    if url is not None:
        url = url.lstrip('/')
    return urljoin(self.base_url, url)

def handle_simple(cls, name):
    try:
        from django.conf import settings
    except ImportError:
        prefix = ''
    else:
        prefix = iri_to_uri(getattr(settings, name, ''))
    return prefix

def get_static_prefix(parser, token):
    """
    Populate a template variable with the static prefix,
    ``settings.STATIC_URL``.

    Usage::

        {% get_static_prefix [as varname] %}

    Examples::

        {% get_static_prefix %}
        {% get_static_prefix as static_prefix %}
    """
    return PrefixNode.handle_token(parser, token, "STATIC_URL")

def render(self, context):
    prefix = self.handle_simple(self.name)
    if self.varname is None:
        return prefix
    context[self.varname] = prefix
    return ''

def as_sql(self, compiler, connection):
    sql, params = compiler.compile(self.lhs)
    if self.rhs:
        return "%s IS NULL" % sql, params
    else:
        return "%s IS NOT NULL" % sql, params

def __init__(self, lhs, rhs):
    self.lhs, self.rhs = lhs, rhs
    self.rhs = self.get_prep_lookup()
    if hasattr(self.lhs, 'get_bilateral_transforms'):
        bilateral_transforms = self.lhs.get_bilateral_transforms()
    else:
        bilateral_transforms = []
    if bilateral_transforms:
        # Warn the user as soon as possible if they are trying to apply
        # a bilateral transformation on a nested QuerySet: that won't work.
        from django.db.models.sql.query import Query  # avoid circular import
        if isinstance(rhs, Query):
            raise NotImplementedError("Bilateral transformations on nested querysets are not implemented.")
    self.bilateral_transforms = bilateral_transforms

def get_prep_lookup(self):
    if hasattr(self.rhs, 'resolve_expression'):
        return self.rhs
    if self.prepare_rhs and hasattr(self.lhs.output_field, 'get_prep_value'):
        return self.lhs.output_field.get_prep_value(self.rhs)
    return self.rhs

def resolve_lookup_value(self, value, can_reuse, allow_joins, simple_col):
    if hasattr(value, 'resolve_expression'):
        kwargs = {'reuse': can_reuse, 'allow_joins': allow_joins}
        if isinstance(value, F):
            kwargs['simple_col'] = simple_col
        value = value.resolve_expression(self, **kwargs)
    elif isinstance(value, (list, tuple)):
        # The items of the iterable may be expressions and therefore need
        # to be resolved independently.
        resolved_values = []
        for sub_value in value:
            if hasattr(sub_value, 'resolve_expression'):
                if isinstance(sub_value, F):
                    resolved_values.append(sub_value.resolve_expression(
                        self, reuse=can_reuse, allow_joins=allow_joins,
                        simple_col=simple_col,
                    ))
                else:
                    resolved_values.append(sub_value.resolve_expression(
                        self, reuse=can_reuse, allow_joins=allow_joins,
                    ))
            else:
                resolved_values.append(sub_value)
        value = tuple(resolved_values)
    return value

def __getitem__(self, k):
    """Retrieve an item or slice from the set of results."""
    if not isinstance(k, (int, slice)):
        raise TypeError(
            'QuerySet indices must be integers or slices, not %s.'
            % type(k).__name__
        )
    assert ((not isinstance(k, slice) and (k >= 0)) or
            (isinstance(k, slice) and (k.start is None or k.start >= 0) and
             (k.stop is None or k.stop >= 0))), \
        "Negative indexing is not supported."

    if self._result_cache is not None:
        return self._result_cache[k]

    if isinstance(k, slice):
        qs = self._chain()
        if k.start is not None:
            start = int(k.start)
        else:
            start = None
        if k.stop is not None:
            stop = int(k.stop)
        else:
            stop = None
        qs.query.set_limits(start, stop)
        return list(qs)[::k.step] if k.step else qs

    qs = self._chain()
    qs.query.set_limits(k, k + 1)
    qs._fetch_all()
    return qs._result_cache[0]

class ChoicesMeta(enum.EnumMeta):
    """A metaclass for creating a enum choices."""

    def __new__(metacls, classname, bases, classdict):
        labels = []
        for key in classdict._member_names:
            value = classdict[key]
            if (
                isinstance(value, (list, tuple)) and
                len(value) > 1 and
                isinstance(value[-1], (Promise, str))
            ):
                *value, label = value
                value = tuple(value)
            else:
                label = key.replace('_', ' ').title()
            labels.append(label)
            # Use dict.__setitem__() to suppress defenses against double
            # assignment in enum's classdict.
            dict.__setitem__(classdict, key, value)
        cls = super().__new__(metacls, classname, bases, classdict)
        cls._value2label_map_ = dict(zip(cls._value2member_map_, labels))
        # Add a label property to instances of enum which uses the enum member
        # that is passed in as "self" as the value to use when looking up the
        # label in the choices.
        cls.label = property(lambda self: cls._value2label_map_.get(self.value))
        return enum.unique(cls)

    def __contains__(cls, member):
        if not isinstance(member, enum.Enum):
            # Allow non-enums to match against member values.
            return member in {x.value for x in cls}
        return super().__contains__(member)

    @property
    def names(cls):
        empty = ['__empty__'] if hasattr(cls, '__empty__') else []
        return empty + [member.name for member in cls]

    @property
    def choices(cls):
        empty = [(None, cls.__empty__)] if hasattr(cls, '__empty__') else []
        return empty + [(member.value, member.label) for member in cls]

    @property
    def labels(cls):
        return [label for _, label in cls.choices]

    @property
    def values(cls):
        return [value for value, _ in cls.choices]

def to_python(self, value):
    if isinstance(value, str) or value is None:
        return value
    return str(value)

def to_python(self, value):
    if value is None:
        return value
    try:
        return int(value)
    except (TypeError, ValueError):
        raise exceptions.ValidationError(
            self.error_messages['invalid'],
            code='invalid',
            params={'value': value},
        )

def _create_test_db(self, verbosity, autoclobber, keepdb=False):
    test_database_name = self._get_test_db_name()

    if keepdb:
        return test_database_name
    if not self.is_in_memory_db(test_database_name):
        # Erase the old test database
        if verbosity >= 1:
            self.log('Destroying old test database for alias %s...' % (
                self._get_database_display_str(verbosity, test_database_name),
            ))
        if os.access(test_database_name, os.F_OK):
            if not autoclobber:
                confirm = input(
                    "Type 'yes' if you would like to try deleting the test "
                    "database '%s', or 'no' to cancel: " % test_database_name
                )
            if autoclobber or confirm == 'yes':
                try:
                    os.remove(test_database_name)
                except Exception as e:
                    self.log('Got an error deleting the old test database: %s' % e)
                    sys.exit(2)
            else:
                self.log('Tests cancelled.')
                sys.exit(1)
    return test_database_name

def _clone_test_db(self, suffix, verbosity, keepdb=False):
    source_database_name = self.connection.settings_dict['NAME']
    target_database_name = self.get_test_db_clone_settings(suffix)['NAME']
    # Forking automatically makes a copy of an in-memory database.
    if not self.is_in_memory_db(source_database_name):
        # Erase the old test database
        if os.access(target_database_name, os.F_OK):
            if keepdb:
                return
            if verbosity >= 1:
                self.log('Destroying old test database for alias %s...' % (
                    self._get_database_display_str(verbosity, target_database_name),
                ))
            try:
                os.remove(target_database_name)
            except Exception as e:
                self.log('Got an error deleting the old test database: %s' % e)
                sys.exit(2)
        try:
            shutil.copy(source_database_name, target_database_name)
        except Exception as e:
            self.log('Got an error cloning the test database: %s' % e)
            sys.exit(2)

def get_group_by_cols(self, alias=None):
    if alias:
        return [Ref(alias, self)]
    external_cols = self.query.get_external_cols()
    if any(col.possibly_multivalued for col in external_cols):
        return [self]
    return external_cols

def generate_added_indexes(self):
    for (app_label, model_name), alt_indexes in self.altered_indexes.items():
        for index in alt_indexes['added_indexes']:
            self.add_operation(
                app_label,
                operations.AddIndex(
                    model_name=model_name,
                    index=index,
                )
            )

def references_field(self, model_name, name, app_label):
    return (
        self.references_model(model_name, app_label) and
        (
            self.order_with_respect_to is None or
            name == self.order_with_respect_to
        )
    )

class AddIndex(IndexOperation):
    """Add an index on a model."""

    def __init__(self, model_name, index):
        self.model_name = model_name
        if not index.name:
            raise ValueError(
                "Indexes passed to AddIndex operations require a name "
                "argument. %r doesn't have one." % index
            )
        self.index = index

    def state_forwards(self, app_label, state):
        model_state = state.models[app_label, self.model_name_lower]
        model_state.options[self.option_name] = [*model_state.options[self.option_name], self.index.clone()]
        state.reload_model(app_label, self.model_name_lower, delay=True)

    def database_forwards(self, app_label, schema_editor, from_state, to_state):
        model = to_state.apps.get_model(app_label, self.model_name)
        if self.allow_migrate_model(schema_editor.connection.alias, model):
            schema_editor.add_index(model, self.index)

    def database_backwards(self, app_label, schema_editor, from_state, to_state):
        model = from_state.apps.get_model(app_label, self.model_name)
        if self.allow_migrate_model(schema_editor.connection.alias, model):
            schema_editor.remove_index(model, self.index)

    def deconstruct(self):
        kwargs = {
            'model_name': self.model_name,
            'index': self.index,
        }
        return (
            self.__class__.__qualname__,
            [],
            kwargs,
        )

    def describe(self):
        return 'Create index %s on field(s) %s of model %s' % (
            self.index.name,
            ', '.join(self.index.fields),
            self.model_name,
        )

    @property
    def migration_name_fragment(self):
        return '%s_%s' % (self.model_name_lower, self.index.name.lower())

def check_dependency(self, operation, dependency):
    """
    Return True if the given operation depends on the given dependency,
    False otherwise.
    """
    # Created model
    if dependency[2] is None and dependency[3] is True:
        return (
            isinstance(operation, operations.CreateModel) and
            operation.name_lower == dependency[1].lower()
        )
    # Created field
    elif dependency[2] is not None and dependency[3] is True:
        return (
            (
                isinstance(operation, operations.CreateModel) and
                operation.name_lower == dependency[1].lower() and
                any(dependency[2] == x for x, y in operation.fields)
            ) or
            (
                isinstance(operation, operations.AddField) and
                operation.model_name_lower == dependency[1].lower() and
                operation.name_lower == dependency[2].lower()
            )
        )
    # Removed field
    elif dependency[2] is not None and dependency[3] is False:
        return (
            isinstance(operation, operations.RemoveField) and
            operation.model_name_lower == dependency[1].lower() and
            operation.name_lower == dependency[2].lower()
        )
    # Removed model
    elif dependency[2] is None and dependency[3] is False:
        return (
            isinstance(operation, operations.DeleteModel) and
            operation.name_lower == dependency[1].lower()
        )
    # Field being altered
    elif dependency[2] is not None and dependency[3] == "alter":
        return (
            isinstance(operation, operations.AlterField) and
            operation.model_name_lower == dependency[1].lower() and
            operation.name_lower == dependency[2].lower()
        )
    # order_with_respect_to being unset for a field
    elif dependency[2] is not None and dependency[3] == "order_wrt_unset":
        return (
            isinstance(operation, operations.AlterOrderWithRespectTo) and
            operation.name_lower == dependency[1].lower() and
            (operation.order_with_respect_to or "").lower() != dependency[2].lower()
        )
    # Field is removed and part of an index/unique_together
    elif dependency[2] is not None and dependency[3] == "foo_together_change":
        return (
            isinstance(operation, (operations.AlterUniqueTogether,
                                   operations.AlterIndexTogether)) and
            operation.name_lower == dependency[1].lower()
        )
    # Unknown dependency. Raise an error.
    else:
        raise ValueError("Can't handle dependency %r" % (dependency,))

def _update_method_wrapper(_wrapper, decorator):
    # _multi_decorate()'s bound_method isn't available in this scope. Cheat by
    # using it on a dummy function.
    @decorator
    def dummy(*args, **kwargs):
        pass
    update_wrapper(_wrapper, dummy)

def create_sql(self, model, schema_editor):
    fields = [model._meta.get_field(field_name) for field_name in self.fields]
    include = [model._meta.get_field(field_name).column for field_name in self.include]
    condition = self._get_condition_sql(model, schema_editor)
    expressions = self._get_index_expressions(model, schema_editor)
    return schema_editor._create_unique_sql(
        model, fields, self.name, condition=condition,
        deferrable=self.deferrable, include=include,
        opclasses=self.opclasses, expressions=expressions,
    )

def _create_unique_sql(
    self, model, fields, name=None, condition=None, deferrable=None,
    include=None, opclasses=None, expressions=None,
):
    if (
        (
            deferrable and
            not self.connection.features.supports_deferrable_unique_constraints
        ) or
        (condition and not self.connection.features.supports_partial_indexes) or
        (include and not self.connection.features.supports_covering_indexes) or
        (expressions and not self.connection.features.supports_expression_indexes)
    ):
        return None

    def create_unique_name(*args, **kwargs):
        return self.quote_name(self._create_index_name(*args, **kwargs))

    compiler = Query(model, alias_cols=False).get_compiler(connection=self.connection)
    table = model._meta.db_table
    columns = [field.column for field in fields]
    if name is None:
        name = IndexName(table, columns, '_uniq', create_unique_name)
    else:
        name = self.quote_name(name)
    if condition or include or opclasses or expressions:
        sql = self.sql_create_unique_index
    else:
        sql = self.sql_create_unique
    if columns:
        columns = self._index_columns(table, columns, col_suffixes=(), opclasses=opclasses)
    else:
        columns = Expressions(table, expressions, compiler, self.quote_value)
    return Statement(
        sql,
        table=Table(table, self.quote_name),
        name=name,
        columns=columns,
        condition=self._index_condition_sql(condition),
        deferrable=self._deferrable_constraint_sql(deferrable),
        include=self._index_include_sql(model, include),
    )

def as_sqlite(self, compiler, connection, **extra_context):
    # Casting to numeric is unnecessary.
    return self.as_sql(compiler, connection, **extra_context)
